const SOURCE_TEXT = new WeakMap();
const SOURCE_ATTRS = new WeakMap();

export function translatePhrase(english, language) {
  if (!language || language === "en") return english;
  const key = CORE_KEYS[english];
  const fixed = (key && translations[language]?.[key]) || PHRASE_MAP.get(english)?.[language];
  if (fixed) return fixed;
  const copy = DYNAMIC_COPY[language] || DYNAMIC_COPY.en;
  let match = english.match(/^(\d+)\s+sample projects? in this state$/i);
  if (match) return `${match[1]} ${SAMPLE_PROJECTS_IN_STATE[language] || SAMPLE_PROJECTS_IN_STATE.en}`;
  match = english.match(/^(\d+)\s+sample projects?$/i);
  if (match) return `${match[1]} ${Number(match[1]) === 1 ? copy.sampleProject : copy.sampleProjects}`;
  match = english.match(/^(\d+)\s+projects?$/i);
  if (match) return `${match[1]} ${Number(match[1]) === 1 ? copy.project : copy.projects}`;
  match = english.match(/^(\d+)\s+locations(?:\s+·\s+mock data may be empty)?$/i);
  if (match) return `${match[1]} ${copy.locations}${english.includes("mock data may be empty") ? ` · ${copy.emptyMock}` : ""}`;
  match = english.match(/^(\d+)\s+shown$/i);
  if (match) return `${match[1]} ${copy.shown}`;
  match = english.match(/^Districts in (.+)$/i);
  if (match) return `${match[1]} ${copy.districtsIn}`;
  match = english.match(/^(.+?)\s+·\s+SAMPLE COUNTS$/i);
  if (match) return `${match[1]} · ${copy.sampleCounts}`;
  match = english.match(/^(.+?)\s+·\s+state view$/i);
  if (match) return `${match[1]} · ${copy.stateView}`;
  match = english.match(/^Show projects in (.+)$/i);
  if (match) return `${copy.show} ${copy.projects} · ${match[1]}`;
  match = english.match(/^Open (.+?) map, (\d+) sample projects?$/i);
  if (match) return `${copy.open} ${match[1]} ${copy.map}, ${match[2]} ${Number(match[2]) === 1 ? copy.sampleProject : copy.sampleProjects}`;
  match = english.match(/^(Department|State|District|Started after):\s*(.+)$/i);
  if (match) return `${translatePhrase(match[1], language)}: ${match[2]}`;
  match = english.match(/^(.+?)\s+(projects|project)$/i);
  if (match) return `${translatePhrase(match[1], language)} ${match[2] === "project" ? copy.project : copy.projects}`;
  return english;
}
function translateAttribute(source, language) {
  const exact = translatePhrase(source, language);
  if (exact !== source) return exact;
  const matches = [...PHRASE_MAP.keys()].filter(phrase => phrase.length >= 9 && source.includes(phrase)).sort((a, b) => b.length - a.length);
  return matches.reduce((value, phrase) => value.replaceAll(phrase, translatePhrase(phrase, language)), source);
}
export function localizeDOM(root, language = "en") {
  if (!root || language === "en") {
    if (language === "en" && root) applyEnglishDOM(root);
    return;
  }
  const doc = root.ownerDocument || document;
  const walker = doc.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!SOURCE_TEXT.has(node)) SOURCE_TEXT.set(node, node.nodeValue);
    const original = SOURCE_TEXT.get(node);
    const trimmed = original.trim();
    if (!trimmed) continue;
    const translated = translatePhrase(trimmed, language);
    node.nodeValue = original.replace(trimmed, translated);
  }
  const elements = root.nodeType === Node.ELEMENT_NODE ? [root, ...root.querySelectorAll("*")] : [...root.querySelectorAll("*")];
  for (const element of elements) {
    const cache = SOURCE_ATTRS.get(element) || new Map();
    for (const name of ["aria-label", "title", "placeholder"]) {
      const current = element.getAttribute(name);
      if (current === null) continue;
      let record = cache.get(name);
      if (!record || current !== record.output) record = { source: current, output: current };
      const output = translateAttribute(record.source, language);
      element.setAttribute(name, output);
      cache.set(name, { source: record.source, output });
    }
    SOURCE_ATTRS.set(element, cache);
  }
}
function applyEnglishDOM(root) {
  const walker = (root.ownerDocument || document).createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) if (SOURCE_TEXT.has(node)) node.nodeValue = SOURCE_TEXT.get(node);
  const elements = root.nodeType === Node.ELEMENT_NODE ? [root, ...root.querySelectorAll("*")] : [...root.querySelectorAll("*")];
  for (const element of elements) {
    const cache = SOURCE_ATTRS.get(element);
    if (!cache) continue;
    for (const [name, record] of cache) if (element.hasAttribute(name)) element.setAttribute(name, record.source);
  }
}

