export function localizedProjectContent(project, language = "en") {
  const pair = PROJECT_COPY[project.id]?.[language];
  if (!pair) return { description: project.description, latestUpdate: project.updates?.[0]?.text || "" };
  return { description: pair[0], latestUpdate: pair[1] };
}
